def solve(inputs: dict) -> float:
    import re
    # Try to extract M, exponent, and mod from inputs
    M = inputs.get('M') or inputs.get('matrix')
    n = inputs.get('n') or inputs.get('exponent') or inputs.get('power')
    mod = inputs.get('mod') or inputs.get('modulus')

    if M is None or n is None or mod is None:
        # parse from a text field
        text = None
        for v in inputs.values():
            if isinstance(v, str):
                text = v
                break
        if text is not None:
            nums = list(map(int, re.findall(r'-?\d+', text)))
            # heuristic parsing not reliable; but attempt
            # find M^exp mod modulus pattern
            mp = re.search(r'M\^(\d+)\s*mod\s*(\d+)', text)
            if mp:
                n = int(mp.group(1))
                mod = int(mp.group(2))
            mm = re.search(r'\[\[(-?\d+),\s*(-?\d+)\],\s*\[(-?\d+),\s*(-?\d+)\]\]', text)
            if mm:
                M = [[int(mm.group(1)), int(mm.group(2))],
                     [int(mm.group(3)), int(mm.group(4))]]

    n = int(n)
    mod = int(mod)
    size = len(M)

    def matmul(A, B):
        R = [[0]*size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                a = A[i][k]
                if a:
                    for j in range(size):
                        R[i][j] = (R[i][j] + a * B[k][j]) % mod
        return R

    # identity
    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    base = [[M[i][j] % mod for j in range(size)] for i in range(size)]
    e = n
    while e > 0:
        if e & 1:
            result = matmul(result, base)
        base = matmul(base, base)
        e >>= 1

    total = 0
    for i in range(size):
        for j in range(size):
            total += result[i][j]
    return float(total)

