def solve(inputs: dict) -> float:
    import re
    rem = inputs.get('remainders') or inputs.get('r')
    mod = inputs.get('moduli') or inputs.get('m')

    if rem is None or mod is None:
        text = None
        for v in inputs.values():
            if isinstance(v, str):
                text = v
                break
        if text is not None:
            # find the two bracketed lists
            lists = re.findall(r'\[([^\]]*)\]', text)
            if len(lists) >= 2:
                rem = list(map(int, re.findall(r'-?\d+', lists[0])))
                mod = list(map(int, re.findall(r'-?\d+', lists[1])))

    rem = [int(x) for x in rem]
    mod = [int(x) for x in mod]

    # CRT
    M = 1
    for m in mod:
        M *= m
    x = 0
    for r, m in zip(rem, mod):
        Mi = M // m
        inv = pow(Mi, -1, m)
        x = (x + r * Mi * inv) % M
    return float(x % M)

